$total = 1162730; while ($true) { $lastLine = (Get-Content -Path backend\scripts\hybrid\hybrid_ingest_errors.log | Select-String "ingested=" | Select-Object -Last 1); if ($lastLine -match "ingested=([0-9,]+)") { $ingested = [int]($matches[1] -replace ",", ""); $percent = [math]::Round(($ingested / $total) * 100); Write-Progress -Activity "Qdrant Hybrid Ingestion" -Status "$percent% Complete ($ingested / 1.16M)" -PercentComplete $percent }; Start-Sleep -Seconds 2 }
